p=json.loads((R/'plan.json').read_text());r=json.loads((R/'report.json').read_text());ctx=json.loads((R/'context.json').read_text());records=reg.read_records(ROOT/'research/automation/registry.jsonl');batch=json.loads((R/'batch.json').read_text());assert len(batch)==len(r['configs'])==18 and r['frozen_plan_sha256']==sha(R/'plan.json');refs=[*p['component_sources'].values(),*p['read_only_anchor_references'].values(),*p['read_only_hold_references'].values()];unique={}
